  // ---------------- GEOCODE (autocomplete location search) ----------------
  // GET /materialSupplier/public/geocode?query=MG Road, Bangalore
  // NOTE: this is now used purely for showing autocomplete SUGGESTIONS in the
  // search box (nice place names as you type). The lat/lng it returns are
  // NOT sent to getPublicProducts anymore — only the displayName text is,
  // which getPublicProducts matches against ContactDetails via `contains`.
  static async geocodeLocation(req, res, next) {
    try {
      const { query, limit = 5 } = req.query;
      if (!query || !query.trim()) {
        return helper_default.failed(res, "Query is required");
      }
      const trimmedQuery = query.trim();
      if (trimmedQuery.length < 2) {
        return helper_default.success(res, "Locations fetched", []);
      }
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 5e3);
      let response;
      try {
        response = await fetch(
          `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(
            trimmedQuery
          )}&limit=${Math.min(10, Number(limit) || 5)}&addressdetails=1&countrycodes=in`,
          {
            headers: {
              "User-Agent": "Karrivo/1.0 (contact@karrivo.com)",
              // REQUIRED — Nominatim blocks generic/missing UA
              Accept: "application/json"
            },
            signal: controller.signal
          }
        );
      } finally {
        clearTimeout(timeoutId);
      }
      const contentType = response.headers.get("content-type") || "";
      if (!response.ok || !contentType.includes("application/json")) {
        const text = await response.text();
        console.error(
          "Nominatim non-JSON response:",
          response.status,
          text.slice(0, 200)
        );
        return helper_default.failed(
          res,
          "Location search is temporarily unavailable. Please try again."
        );
      }
      const data2 = await response.json();
      const results = data2.filter((r5) => r5.lat && r5.lon).map((r5) => ({
        displayName: r5.display_name,
        lat: Number(r5.lat),
        lng: Number(r5.lon),
        state: r5.address?.state || null,
        city: r5.address?.city || r5.address?.town || r5.address?.village || null,
        country: r5.address?.country || null
      }));
      return helper_default.success(res, "Locations fetched", results);
    } catch (error2) {
      if (error2.name === "AbortError") {
        return helper_default.failed(
          res,
          "Location search timed out. Please try again."
        );
      }
      next(error2);
    }
  }
